import calendar
from datetime import date, timedelta

_WEEKDAYS = {
    "MO": 0,
    "TU": 1,
    "WE": 2,
    "TH": 3,
    "FR": 4,
    "SA": 5,
    "SU": 6,
}


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split(" ")
    freq = parts[0]
    k = int(parts[1])
    result: list[str] = []

    if freq == "DAILY":
        for i in range(count):
            result.append((start_date + timedelta(days=i * k)).isoformat())
        return result

    if freq == "WEEKLY":
        target_days = sorted(_WEEKDAYS[code] for code in parts[2].split(","))
        week0_monday = start_date - timedelta(days=start_date.weekday())
        w = 0
        while len(result) < count:
            monday = week0_monday + timedelta(weeks=w)
            for wd in target_days:
                d = monday + timedelta(days=wd)
                if d >= start_date:
                    result.append(d.isoformat())
                    if len(result) == count:
                        break
            w += k
        return result

    if freq == "MONTHLY":
        base_months = start_date.year * 12 + (start_date.month - 1)
        m = 0
        if len(parts) == 3:
            target_day = int(parts[2])
            while len(result) < count:
                year, month_zero = divmod(base_months + m, 12)
                month = month_zero + 1
                days_in_month = calendar.monthrange(year, month)[1]
                day = days_in_month if target_day == -1 else target_day
                if day <= days_in_month:
                    d = date(year, month, day)
                    if d >= start_date:
                        result.append(d.isoformat())
                m += k
        else:
            nth = int(parts[2])
            wd_idx = _WEEKDAYS[parts[3]]
            while len(result) < count:
                year, month_zero = divmod(base_months + m, 12)
                month = month_zero + 1
                first_wd, days_in_month = calendar.monthrange(year, month)
                if nth == -1:
                    last_wd = (first_wd + days_in_month - 1) % 7
                    day = days_in_month - (last_wd - wd_idx) % 7
                else:
                    first_occ = 1 + (wd_idx - first_wd) % 7
                    day = first_occ + (nth - 1) * 7
                if day <= days_in_month:
                    d = date(year, month, day)
                    if d >= start_date:
                        result.append(d.isoformat())
                m += k
        return result

    if freq == "YEARLY":
        mm_str, dd_str = parts[2].split("-")
        month = int(mm_str)
        day = int(dd_str)
        y_offset = 0
        while len(result) < count:
            year = start_date.year + y_offset
            try:
                d = date(year, month, day)
            except ValueError:
                pass
            else:
                if d >= start_date:
                    result.append(d.isoformat())
            y_offset += k
        return result

    raise ValueError(f"Unsupported rule: {rule}")
